changes.oldText:
// SSE live-delivery probe: connect stream FIRST, then send, then count steps.
const BASE = "http://127.0.0.1:46321/dsh-mini/api";

async function main() {
  // 1) new session
  const nr = await fetch(BASE + "/threads/new", { method: "POST" });
  const { id } = await nr.json();
  console.log("session:", id);

  // 2) open SSE stream
  const ac = new AbortController();
  const streamPromise = (async () => {
    const r = await fetch(BASE + "/threads/" + encodeURIComponent(id) + "/stream", { signal: ac.signal });
    const reader = r.body.getReader();
    const dec = new TextDecoder();
    let buf = "";
    let steps = 0;
    const types = new Set();
    let statusEvents = [];
    while (true) {
      const { done, value } = await reader.read();
      if (done) break;
      buf += dec.decode(value, { stream: true });
      let idx;
      while ((idx = buf.indexOf("\n\n")) >= 0) {
        const frame = buf.slice(0, idx);
        buf = buf.slice(idx + 2);
        if (frame.startsWith("event: step")) {
          steps++;
          const dataLine = frame.split("\n").find((l) => l.startsWith("data: "));
          if (dataLine) {
            try {
              const d = JSON.parse(dataLine.slice(6));
              types.add(d.type);
              if (d.type === "status") statusEvents.push(d);
            } catch {}
          }
        }
      }
    }
    return { steps, types: [...types], statusEvents };
  })();

  // 3) wait a beat, then send
  await new Promise((r) => setTimeout(r, 1000));
  const sendRes = await fetch(BASE + "/threads/" + encodeURIComponent(id) + "/send", {
    method: "POST",
    headers: { "content-type": "application/json" },
    body: JSON.stringify({ text: "回复两个字：收到" }),
  });
  console.log("send:", sendRes.status);

  // 4) read for up to 45s or until turn-end
  const start = Date.now();
  let result = null;
  while (Date.now() - start < 45000) {
    await new Promise((r) => setTimeout(r, 1000));
    // peek: can't easily peek a promise; use side-channel file
    const done = await Promise.race([streamPromise.then(() => "closed"), new Promise((r) => setTimeout(() => r("waiting"), 1000))]);
    if (done === "closed") { result = await streamPromise; break; }
    if (Date.now() - start > 40000 && done === "waiting") break;
  }
  ac.abort();
  try { result = result || await streamPromise; } catch {}
  console.log("RESULT:", JSON.stringify(result));
}

main().catch((e) => { console.error("FAIL:", e && e.message); process.exit(1); });

