} else {
  // 工作区分组：cwd 取最后一段作标题，同名才回退完整路径
  const groups = new Map();
  for (const t of threads) {
    const key = (t.cwd || t.workspace || "").trim() || "(未指定工作区)";
    if (!groups.has(key)) groups.set(key, []);
    groups.get(key).push(t);
  }
  const nameCount = new Map();
  for (const k of groups.keys()) {
    const base = String(k).split(/[\\/]/).filter(Boolean).pop() || k;
    nameCount.set(base, (nameCount.get(base) || 0) + 1);
  }
  const keys = [...groups.keys()].sort((a, b) => a.localeCompare(b));
  for (const key of keys) {
    const list = groups.get(key);
    const base = String(key).split(/[\\/]/).filter(Boolean).pop() || key;
    const labelText = (nameCount.get(base) > 1 ? key : base) + "（" + list.length + "）";
    const section = document.createElement("section");
    section.className = "thread-section";
    const label = document.createElement("div");
    label.className = "thread-section-label";
    label.textContent = labelText;
    label.title = key;
