function renderSegment(seg, batched) {
  if (!seg) return;
  switch (seg.type) {
    case "thinking": {
      if (!curThinking || batched) {
        curThinking = document.createElement("div");
        curThinking.className = "message assistant";
        const wrap = document.createElement("div");
        wrap.className = "bubble-wrap";
        const inner = document.createElement("div");
        inner.className = "process-thinking";
        wrap.appendChild(inner);
        curThinking.appendChild(wrap);
        curThinking.classList.add("msg-in");
        thread.appendChild(curThinking);
      }
      curThinking.firstChild.firstChild.textContent += seg.text || "";
      scrollDown();
      break;
    }
    case "assistant": {
      if (!curMsg || batched) newAssistantBlock();
      if (curMsg._bubble) curMsg._bubble.textContent += seg.text || "";
      scrollDown();
      break;
    }
    case "tools": {
      if (!curMsg || batched) newAssistantBlock();
      for (const it of seg.items || []) renderToolPill(it);
      scrollDown();
      break;
    }
    case "user": {
      const um = document.createElement("div");
      um.className = "message user";
      const wrap = document.createElement("div");
      wrap.className = "bubble-wrap";
      const meta = document.createElement("div");
      meta.className = "meta";
      meta.innerHTML = '<span class="mt">桌面端</span>';
      const bubble = document.createElement("div");
      bubble.className = "bubble";
      bubble.textContent = seg.text || "";
      wrap.append(meta, bubble);
      um.appendChild(wrap);
      um.classList.add("msg-in");
      thread.appendChild(um);
      curMsg = null; curThinking = null;
      scrollDown();
      break;
    }
    case "status": {
      if (seg.status === "turn-start") setBusy(true);
      if (seg.status === "turn-end") { setBusy(false); showNotice(seg.reason === "completed" ? "本轮完成" : seg.reason === "error" ? "本轮出错" : "已停止", seg.reason === "error"); }
      break;
    }
    case "model": {
      setModelBadge({ provider: seg.provider, model: seg.model, reasoningEffort: seg.reasoningEffort });
      break;
    }
    case "title": {
      if (seg.title) {
        threadName.textContent = seg.title;
        const t = threads.find(x => x.id === currentId);
