function renderSegments(segs, batched) {
  if (!segs || !segs.length) return;
  let idx = 0;
  if (!batched) {
    for (; idx < segs.length; idx++) renderSegment(segs[idx], false);
    return;
  }
  renderBatch = true;
  const CHUNK = 100;
  (function next() {
    if (idx >= segs.length) {
      renderBatch = false;
      scrollDown();
      return;
    }
    const end = Math.min(idx + CHUNK, segs.length);
    for (; idx < end; idx++) renderSegment(segs[idx], true);
    requestAnimationFrame(next);
  })();
}

// ---------- 历史 ----------
async function loadHistory(id, merge) {
  const key = "dshhist:" + id;
  let cached = null;
  try { cached = JSON.parse(localStorage.getItem(key) || "null"); } catch {}
  const cacheHit = !merge && cached && Array.isArray(cached.segments) && cached.segments.length > 0;
  if (cacheHit) {
    // 缓存立即（秒开）渲染，后台 fetch 只核对 revision 是否新增
    lastSeqMax = cached.rev || 0;
    curMsg = null; curThinking = null;
    thread.innerHTML = '<div class="day-note">' + esc(cached.title || id) + "</div>";
    renderSegments(cached.segments, true);
    if (cached.model) setModelBadge(cached.model);
    else refreshModel();
  }
  try {
    const r = await fetch(apiBase() + "/threads/" + encodeURIComponent(id) + "/history", { headers: authHeader() });
    if (!r.ok) return;
    const hist = await r.json();
    if (!merge) {
      if (cacheHit && (hist.revision || 0) === (cached.rev || 0)) {
        // 无新增内容：缓存已渲染，只同步标题
        if (hist.title && threadName.textContent !== hist.title) threadName.textContent = hist.title;
      } else {
        thread.innerHTML = '<div class="day-note">' + esc(hist.title || id) + "</div>";
        curMsg = null; curThinking = null; lastSeqMax = 0;
        if (hist.segments && hist.segments.length) renderSegments(hist.segments, true);
        else for (const s of hist.steps || []) applyStep(s, true);
      }
    } else {
      // merge 模式：只补 seqMax 大于已渲染基准的新段（SSE 断连兜底，避免全量重绘闪烁）
      const fresh = (hist.segments || []).filter(sg => sg.seqMax > lastSeqMax);
      if (fresh.length) {
        renderBatch = true;
        for (const sg of fresh) renderSegment(sg, false);
        renderBatch = false;
      }
    }
    lastSeqMax = Math.max(lastSeqMax, hist.revision || 0);
    if (hist.model) setModelBadge(hist.model);
    else refreshModel();
    scrollDown();
    try {
      localStorage.setItem(key, JSON.stringify({ rev: hist.revision || 0, segments: hist.segments || [], title: hist.title || "", model: hist.model || null, at: Date.now() }));
    } catch {}
  } catch {}
}

