function newThinkingBlock(expand) {
  curThinking = document.createElement("div");
  curThinking.className = "message assistant";
  const wrap = document.createElement("div");
  wrap.className = "bubble-wrap";
  const block = document.createElement("div");
  block.className = "think-block";
  const toggle = document.createElement("button");
  toggle.type = "button";
  toggle.className = "think-toggle" + (expand ? "" : " closed");
  toggle.innerHTML = '<span>💭 思考过程</span><span class="tw-arrow">▾</span>';
  const body = document.createElement("div");
  body.className = "think-body" + (expand ? "" : " closed");
  block.append(toggle, body);
  toggle.addEventListener("click", () => {
    const cl = body.classList.toggle("closed");
    toggle.classList.toggle("closed", cl);
    thinkUserCollapsed = cl;
  });
  wrap.appendChild(block);
