// ---- QQ 开放平台机器人渠道（P2，SPEC §7 / docs/qq-bot-dsh-report.md）----
const qqLogger = createChannelLogger(logsDir, "qq");
const qqGate = createChannelGate({ channel: "qq", dedupe, quota: inboundQuota, logger: qqLogger });
const qqBinds = new Map(); // 群: convId / 私聊: open_id -> rec（/attach 接管）
const qq = createQqAdapter({
  // 设置命名空间键是 qqBotAppId/qqBotToken/qqSandbox，适配器内部用 appId/appSecret/qqSandbox
  getConfig: () => {
    const c = liveConfig() || {};
    return { appId: c.qqBotAppId, appSecret: c.qqBotToken, qqSandbox: c.qqSandbox };
  },
  onState: (s) => {
    console.log("[openclaw-bridge] qq: " + JSON.stringify(s));
  },
  onMessage: async (m) => {
    const text = String(m.text || "").trim();
    if (!text) return;
    const cfg = liveConfig() || {};
    if (!isChannelEnabled("qq", cfg)) {
      qqLogger.info("qq disabled by config — message ignored");
      return;
    }
    const uid = String(m.conv.memberId || m.conv.id || "");
    const gate = qqGate(m); // 去重(channel:eventId) + 限流
    if (!gate.allowed) return;
    if (!userAllowed(effectiveWhitelist("qq", cfg), uid)) {
      qqLogger.warn("message from non-allowlisted user ignored: " + uid);
      return;
    }
    const replyTo = async (t) => {
      for (const seg of segmentReply(t)) {
        try {
          await qq.send(m.conv, seg, { msgId: m.msgId });
        } catch (e) {
          qqLogger.warn("qq send failed: " + String((e && e.message) || e));
        }
      }
    };
    const identity = m.conv.kind === "group" ? String(m.conv.id || "") : uid;
    const key = "qq-" + sanitizeKey(identity);
    if (text.startsWith("/")) {
      try {
        await handleChannelCommand(ctx, { binds: qqBinds, key, from: identity, text, replyTo });
      } catch (err) {
        console.error("[openclaw-bridge] qq command failed: " + String(err?.message || err));
        await replyTo("指令执行出错：" + String(err?.message || err).slice(0, 400));
      }
      return;
    }
    // 普通消息：私聊每用户一会话；群聊每群一会话 + 群友署名注入（A-03）
    const signed = memberPrefix(m, cfg.groupSignature !== "0") + text;
    try {
      let rec = qqBinds.get(identity);
      if (!rec) {
        const ws = String(cfg.workspace || "").trim();
        rec = await ensureAgent(ctx, key, ws || undefined);
        qqBinds.set(identity, rec);
      }
      const task = () => runTurn(rec, [signed], null);
      const work = rec.chain.then(task, task);
      rec.chain = work.then(
        () => {},
        () => {}
      );
      const result = await work;
      const reply = (result.text || "").trim() || "（本轮没有文本回复）";
      await replyTo(reply);
      qqLogger.info("reply to " + key + " sent");
    } catch (err) {
      console.error("[openclaw-bridge] qq turn failed: " + String(err?.message || err));
      await replyTo("处理出错：" + String(err?.message || err).slice(0, 500));
    }
  },
  logger: qqLogger,
});
adapters.set("qq", qq);

