/**
 * @dsh-external/dsh-agent-squad — 多 Agent 协作指挥室（host 半边）
 *
 * 星型委派编排：Captain（会话级 agent，ctx.agents）负责把 Mission 分解为任务图、
 * 评审回合成果、收敛报告；Workers（subagent，ctx.subagents，'spawn'/maxDepth:1）
 * 无头并行执行任务；引擎在 Mission 状态机上推进回合，预算闸门（gate）默认开启。
 *
 * P1（本文件）：Mission 状态机 + 回合循环 + 闸门 + SSE 事件总线 + 5 个 squad_* 工具
 * + REST API（/dsh-agent-squad/api/*）。持久化 ~/.dsh/dsh-agent-squad/missions/<id>/。
 */
import type { Context } from '@deepseek-ai/cordis'
import { defineTool } from '@deepseek-ai/dsh-tools'
import { createUserMessage } from '@deepseek-ai/dsh-llm'
import { SessionId } from '@deepseek-ai/dsh-session'
import z from '@deepseek-ai/schemastery'
import {
  appendFileSync, existsSync, mkdirSync, readFileSync, renameSync, writeFileSync,
} from 'node:fs'
import { join } from 'node:path'
import { homedir } from 'node:os'
import { randomUUID } from 'node:crypto'

// ════════════════════════════════════════════════════════════════════════
// 类型
// ════════════════════════════════════════════════════════════════════════

type AppContext = Context & {
  tools: any
  webServer: any
  subagents: any
  agents: any
  get(name: string): any
}

export interface Config {
  dataDir: string
  squadProvider: string
  defaultMaxRounds: number
  roundTokenCap: number
  gateRequired: boolean
}

export const Config = z.object({
  dataDir: z.string().default(''),
  squadProvider: z.string().default('spawn'),
  defaultMaxRounds: z.number().min(1).max(10).default(3),
  roundTokenCap: z.number().min(500).default(4000),
  gateRequired: z.boolean().default(true),
})

interface RoleDef {
  id: string
  name: string
  system: string
}

interface TeamDef {
  id: string
  name: string
  description: string
  roles: RoleDef[]
}

interface TaskRec {
  id: string
  title: string
  detail: string
  assignee: string
  status: 'pending' | 'running' | 'done' | 'failed'
  result?: string
  artifact?: string
}

interface RoundRec {
  index: number
  phase: 'dispatch' | 'collect' | 'review'
  startedAt: number
  endedAt?: number
  gate: 'none' | 'pending' | 'approved' | 'rejected'
  feedback?: string
  tasks: TaskRec[]
}

interface Mission {
  id: string
  objective: string
  constraints?: string
  expectation?: string
  teamId: string
  status: MissionStatus
  paused: boolean
  cancelled: boolean
  createdAt: number
  updatedAt: number
  round: number
  maxRounds: number
  gateRequired: boolean
  rounds: RoundRec[]
  artifacts: string[]
  captain?: { sessionId: string; cwd: string }
  report?: string
  error?: string
}

type MissionStatus =
  | 'planning'
  | 'dispatching'
  | 'collecting'
  | 'awaiting_gate'
  | 'reviewing'
  | 'converged'
  | 'cancelled'
