// ════════════════════════════════════════════════════════════════════════
// 提示词常量（静态模板；使命字段在消息尾动态拼接，符合缓存原则）
// ════════════════════════════════════════════════════════════════════════

function decomposePrompt(mission: Mission, roles: string, retryNote?: string): string {
  const lines = [
    '你是 Mission Captain（任务分解员）。把下面的目标分解成 2~4 个可并行执行的任务，',
    '每个任务必须指派给一个可用角色。任务要具体、可独立交付、可验收。',
    '',
    `可用角色：${roles}`,
    '',
    `目标：${mission.objective}`,
  ]
  if (mission.constraints) lines.push(`约束：${mission.constraints}`)
  if (mission.expectation) lines.push(`验收期望：${mission.expectation}`)
  if (retryNote) lines.push('', `注意（上次解析失败/评审意见）：${retryNote}`)
  lines.push(
    '',
    '只输出一个 JSON 对象，不要任何解释、不要 Markdown 代码块以外的文字：',
    '{"tasks":[{"title":"任务标题","detail":"任务详情","assignee":"角色id"}]}',
  )
  return lines.join('\n')
}

function workerPrompt(mission: Mission, role: RoleDef, task: TaskRec, feedback?: string): string {
  const lines = [
    `你的角色是「${role.name}」：${role.system}`,
    '',
    '你是一个多 Agent 协作小队的一员，负责下面这个具体任务。请直接产出成果（Markdown 文本），',
    '聚焦交付本身，不要寒暄，不要讨论协作流程。',
    '',
    `任务标题：${task.title}`,
    `任务详情：${task.detail}`,
  ]
  if (feedback) lines.push('', `上一轮评审意见：${feedback}`)
  lines.push('', `任务背景目标：${mission.objective}`)
  if (mission.constraints) lines.push(`约束：${mission.constraints}`)
  return lines.join('\n')
}

function reviewPrompt(mission: Mission, summary: string): string {
  const lines = [
    '你是 Mission Captain（评审员）。判断本轮小队成果是否达标。',
    '',
    `目标：${mission.objective}`,
  ]
  if (mission.expectation) lines.push(`验收期望：${mission.expectation}`)
  lines.push('', '本轮任务与成果：', summary,
    '',
    '只输出一个 JSON 对象，不要任何解释：',
    '{"approved":true或false,"note":"一句话结论","followups":[{"title":"下轮任务标题","detail":"下轮任务详情"}]}',
    'approved=false 时 followups 给出下轮需要补做的任务；approved=true 时 followups 可为空数组。')
  return lines.join('\n')
}

function reportPrompt(mission: Mission, summary: string): string {
  const lines = [
    '你是 Mission Captain。任务已完成（或已达最大轮次），请写最终交付报告。',
    '',
    `目标：${mission.objective}`,
  ]
  if (mission.constraints) lines.push(`约束：${mission.constraints}`)
  if (mission.expectation) lines.push(`验收期望：${mission.expectation}`)
  lines.push('', '各轮成果：', summary)
  lines.push('', '只输出 Markdown 报告正文：结论摘要、交付内容、未完成项与风险、后续建议。')
  return lines.join('\n')
}

// ════════════════════════════════════════════════════════════════════════
// 通用工具函数
// ════════════════════════════════════════════════════════════════════════

function truncate(s: string | undefined, n: number): string {
  if (!s) return ''
  return s.length > n ? s.slice(0, n) + '…' : s
}

function messageText(content: any): string {
  if (typeof content === 'string') return content
  if (Array.isArray(content)) {
    return content.filter((b: any) => b && b.type === 'text').map((b: any) => b.text || '').join('')
  }
  return ''
}

function extractJson(text: string): any {
  if (!text) return null
  const fence = text.match(/```(?:json)?\s*([\s\S]*?)```/i)
  const body = fence ? fence[1] : text
  const start = body.indexOf('{')
  const end = body.lastIndexOf('}')
  if (start >= 0 && end > start) {
    try { return JSON.parse(body.slice(start, end + 1)) } catch { /* fallthrough */ }
  }
  try { return JSON.parse(body) } catch { return null }
}

function normalizeTaskList(list: any[], prefix: string): TaskRec[] | null {
  const out: TaskRec[] = []
  for (let i = 0; i < list.length; i++) {
    const t = list[i]
    if (!t || typeof t.title !== 'string' || !t.title.trim()) continue
    out.push({
      id: `${prefix}-${i + 1}`,
      title: t.title.trim(),
      detail: typeof t.detail === 'string' ? t.detail.trim() : '',
      assignee: typeof t.assignee === 'string' && t.assignee ? t.assignee : 'executor',
      status: 'pending',
    })
  }
  return out.length ? out : null
}

function snapshot(mission: Mission): any {
  return {
    id: mission.id,
    objective: mission.objective,
    teamId: mission.teamId,
    status: mission.status,
    paused: mission.paused,
    round: mission.round,
    maxRounds: mission.maxRounds,
    gateRequired: mission.gateRequired,
    roundCount: mission.rounds.length,
    current: mission.rounds.length ? mission.rounds[mission.rounds.length - 1] : null,
    rounds: mission.rounds,
    artifacts: mission.artifacts,
    captain: mission.captain ? { sessionId: mission.captain.sessionId } : null,
    report: mission.report ? truncate(mission.report, 5000) : undefined,
    error: mission.error,
    createdAt: mission.createdAt,
    updatedAt: mission.updatedAt,
  }
}

// ════════════════════════════════════════════════════════════════════════
// 引擎状态（每插件实例一份；热重载后重置属正常）
// ════════════════════════════════════════════════════════════════════════

interface Engine {
  ctx: AppContext
  config: Config
  baseDir: string
  missionsDir: string
  missions: Map<string, Mission>
  captainHandles: Map<string, any>
  gateWaiters: Map<string, (a: GateAction) => void>
  pauseWaiters: Map<string, () => void>
  aborters: Map<string, AbortController>
  sse: Map<string, Set<(evt: any) => void>>
  logFile: string
}

function engineLog(eng: Engine, msg: string): void {
  try {
    appendFileSync(eng.logFile, `[${new Date().toISOString()}] ${msg}\n`)
  } catch { /* 日志失败静默 */ }
}

function pushEvent(eng: Engine, missionId: string, evt: any): void {
  const listeners = eng.sse.get(missionId)
  if (listeners) {
    for (const fn of [...listeners]) {
      try { fn(evt) } catch { /* 单个监听失败不影响 */ }
    }
  }
}

function commitMission(eng: Engine, mission: Mission): void {
  mission.updatedAt = Date.now()
  const dir = join(eng.missionsDir, mission.id)
  mkdirSync(dir, { recursive: true })
  const tmp = join(dir, 'mission.json.tmp')
  const final = join(dir, 'mission.json')
  writeFileSync(tmp, JSON.stringify(mission, null, 2), 'utf8')
  renameSync(tmp, final)
  pushEvent(eng, mission.id, { type: 'mission/update', mission: snapshot(mission) })
}

function loadMission(eng: Engine, id: string): Mission | null {
  const file = join(eng.missionsDir, id, 'mission.json')
  if (!existsSync(file)) return null
  try { return JSON.parse(readFileSync(file, 'utf8')) as Mission } catch { return null }
}

function getTeam(teamId: string): TeamDef {
  return TEAMS.find((t) => t.id === teamId) ?? TEAMS[0]
}

// ════════════════════════════════════════════════════════════════════════
// Captain（会话级 agent）交互
// ════════════════════════════════════════════════════════════════════════

async function ensureCaptain(eng: Engine, mission: Mission): Promise<any> {
  const existing = eng.captainHandles.get(mission.id)
  if (existing) return existing
  const cwd = join(eng.missionsDir, mission.id, 'workspace')
  mkdirSync(cwd, { recursive: true })
  let agentOptions: any = {}
  try {
    const sel = eng.ctx.get('agentDefaultModel')?.currentSelection?.()
    if (sel && sel.provider && sel.model) {
      agentOptions = {
        provider: sel.provider,
        model: sel.model,
        ...(sel.reasoningEffort ? { reasoningEffort: sel.reasoningEffort } : {}),
      }
    }
  } catch { /* 无默认模型则交给 agent 自身默认 */ }
  const sessionId = SessionId('dsh-agent-squad-' + randomUUID())
  const { agent } = await eng.ctx.agents.create({
    sessionId,
    meta: { cwd },
    agentOptions,
    setup: () => { /* P1 无需额外装配 */ },
  })
  mission.captain = { sessionId: agent.session.id, cwd }
  eng.captainHandles.set(mission.id, agent)
  commitMission(eng, mission)
  engineLog(eng, `mission=${mission.id} captain created session=${agent.session.id}`)
  return agent
}

function readCaptainText(eng: Engine, mission: Mission): string {
  const sessionId = mission.captain?.sessionId
  if (!sessionId) return ''
  const store = eng.ctx.get('sessions')
  let events: any[] = []
  if (store && store.get) {
    const session = store.get(sessionId)
    if (session && Array.isArray(session.events)) events = session.events
  }
  // 兜底：从 handle 的 session 直接取
  const handle = eng.captainHandles.get(mission.id)
  if (!events.length && handle && handle.session && Array.isArray(handle.session.events)) {
    events = handle.session.events
  }
  for (let i = events.length - 1; i >= 0; i--) {
    const ev = events[i]
    if (ev && ev.type === 'assistant/message') {
      const text = messageText(ev.data?.message?.content)
      if (text.trim()) return text.trim()
    }
    if (ev && ev.type === 'turn/end') break // 越过本回合边界就不再回溯更早消息
  }
  return ''
}

async function captainAsk(eng: Engine, mission: Mission, text: string): Promise<string> {
  const handle = await ensureCaptain(eng, mission)
  await handle.followup(createUserMessage({
    content: [{ type: 'text', text }],
    source: { kind: 'user' },
  }))
  await handle.whenIdle()
  return readCaptainText(eng, mission)
}

// ════════════════════════════════════════════════════════════════════════
// 回合推进
// ════════════════════════════════════════════════════════════════════════

async function pausePoint(eng: Engine, mission: Mission): Promise<void> {
  if (!mission.paused || mission.cancelled) return
  engineLog(eng, `mission=${mission.id} paused at phase boundary`)
  await new Promise<void>((resolve) => {
    eng.pauseWaiters.set(mission.id, resolve)
  })
}

function gateWaiter(eng: Engine, mission: Mission): Promise<GateAction> {
  return new Promise<GateAction>((resolve) => {
    eng.gateWaiters.set(mission.id, resolve)
  })
}

async function dispatchRound(
  eng: Engine,
  mission: Mission,
  round: RoundRec,
  controller: AbortController,
): Promise<void> {
  mission.status = 'dispatching'
  commitMission(eng, mission)
  const team = getTeam(mission.teamId)
  for (const task of round.tasks) {
    if (mission.cancelled) return
    await pausePoint(eng, mission)
    task.status = 'running'
    commitMission(eng, mission)
    const role = team.roles.find((r) => r.id === task.assignee) ?? team.roles[0]
    const prompt = workerPrompt(mission, role, task, round.feedback)
    let run: any
    let failedMsg: string | undefined
    try {
      run = await eng.ctx.subagents.start(eng.config.squadProvider, {
        label: `m${mission.id} ${task.title}`,
        prompt: [{ type: 'text', text: prompt }],
        maxDepth: 1,
        ...(controller.signal ? { signal: controller.signal } : {}),
      })
      const result = await run.result
      if (result.stopReason !== 'completed') {
        failedMsg = `worker 未正常完成: ${result.stopReason}`
      } else {
        const text = messageText(result.output)
        if (text.trim()) {
          const name = `artifact-${task.id}.md`
          writeFileSync(join(eng.missionsDir, mission.id, 'artifacts', name), text, 'utf8')
          task.artifact = name
          task.result = text
          task.status = 'done'
          if (!mission.artifacts.includes(name)) mission.artifacts.push(name)
        } else {
          failedMsg = 'worker 无产出文本'
        }
      }
    } catch (e: any) {
      if (controller.signal.aborted || mission.cancelled) {
        task.status = 'failed'
        task.result = '已取消'
      } else {
        failedMsg = '派发失败: ' + String(e && e.message ? e.message : e)
      }
    } finally {
      if (run && typeof run.dispose === 'function') {
        try { await run.dispose() } catch { /* 释放即可 */ }
      }
    }
    if (failedMsg) {
      task.status = 'failed'
      task.result = truncate(failedMsg, 500)
    }
    commitMission(eng, mission)
  }
  const pending = round.tasks.some((t) => t.status === 'pending' || t.status === 'running')
  mission.status = pending ? 'collecting' : 'collecting'
  round.phase = 'collect'
  round.endedAt = Date.now()
  commitMission(eng, mission)
}

async function reviewRound(
  eng: Engine,
  mission: Mission,
  round: RoundRec,
): Promise<{ approved: boolean; note?: string; followups: any[] }> {
  mission.status = 'reviewing'
  round.phase = 'review'
  commitMission(eng, mission)
  const summary = round.tasks
    .map((t) => `### ${t.title}（${t.assignee} · ${t.status === 'done' ? '✓ 完成' : '✗ 失败'}）\n${truncate(t.result || '（无产出）', 1200)}`)
    .join('\n\n')
  const text = await captainAsk(eng, mission, reviewPrompt(mission, summary))
  const json = extractJson(text)
  if (!json) {
    return { approved: false, note: '评审未返回 JSON，视为不通过：' + truncate(text, 200), followups: [] }
  }
  return {
    approved: json.approved === true,
    note: typeof json.note === 'string' ? json.note : undefined,
    followups: Array.isArray(json.followups) ? json.followups : [],
  }
}

async function convergeMission(eng: Engine, mission: Mission): Promise<void> {
  const summary = mission.rounds
    .map((r) => `## 第 ${r.index + 1} 轮\n` + r.tasks
      .map((t) => `### ${t.title}（${t.status === 'done' ? '✓' : '✗'}）\n${truncate(t.result || '', 800)}`)
      .join('\n'))
    .join('\n\n')
  const text = await captainAsk(eng, mission, reportPrompt(mission, summary))
  mission.report = text
  const dir = join(eng.missionsDir, mission.id, 'artifacts')
  mkdirSync(dir, { recursive: true })
  const name = 'report.md'
  writeFileSync(join(dir, name), text, 'utf8')
  if (!mission.artifacts.includes(name)) mission.artifacts.push(name)
  commitMission(eng, mission)
}

// ════════════════════════════════════════════════════════════════════════
// Mission 主循环
// ════════════════════════════════════════════════════════════════════════

async function runMission(eng: Engine, mission: Mission): Promise<void> {
  const controller = new AbortController()
  eng.aborters.set(mission.id, controller)
  let captain: any
  try {
    mission.status = 'planning'
    commitMission(eng, mission)
    captain = await ensureCaptain(eng, mission)

    // 分解（1 次重试）
    const team = getTeam(mission.teamId)
    const roles = team.roles.map((r) => `${r.id}(${r.name})`).join('、')
    let taskList: TaskRec[] | null = null
    let lastErr = ''
    for (let attempt = 0; attempt < 2 && !taskList; attempt++) {
      const text = await captainAsk(eng, mission, decomposePrompt(mission, roles, attempt ? lastErr : undefined))
      const json = extractJson(text)
      const rawList = json ? (Array.isArray(json) ? json : json.tasks) : null
      taskList = normalizeTaskList(rawList, `r${mission.rounds.length + 1}`)
      if (!taskList) {
        lastErr = '分解结果无法解析为任务列表：' + truncate(text, 200)
        mission.error = lastErr
        commitMission(eng, mission)
      }
    }
    if (!taskList) throw new Error(lastErr || '分解失败')

    // 回合循环
    let tasks = taskList
    let roundFeedback: string | undefined
    for (let roundNo = 0; roundNo < mission.maxRounds; roundNo++) {
      if (mission.cancelled) break
      await pausePoint(eng, mission)
      const round: RoundRec = {
        index: roundNo,
        phase: 'dispatch',
        startedAt: Date.now(),
        gate: 'none',
        tasks: tasks.map((t) => ({ ...t })),
      }
      if (roundFeedback) round.feedback = roundFeedback
      mission.round = roundNo
      mission.rounds.push(round)
      commitMission(eng, mission)

      await dispatchRound(eng, mission, round, controller)
      if (mission.cancelled) break

      const failed = round.tasks.filter((t) => t.status === 'failed')
      if (failed.length && roundNo + 1 < mission.maxRounds && round.tasks.length > 1) {
        roundFeedback = failed
          .map((t) => `任务「${t.title}」失败：${truncate(t.result || '', 300)}`)
          .join('\n')
        tasks = failed.map((t) => ({
          title: t.title,
          detail: t.detail + '\n（重试）',
          assignee: t.assignee,
        }))
        continue
      }

      // 预算闸门
      if (mission.gateRequired) {
        round.gate = 'pending'
        mission.status = 'awaiting_gate'
        commitMission(eng, mission)
        pushEvent(eng, mission.id, { type: 'gate/pending', missionId: mission.id, round: roundNo })
        const action = await gateWaiter(eng, mission)
        if (mission.cancelled) break
        round.gate = action.action === 'approve' ? 'approved' : 'rejected'
        if (action.action === 'reject' && roundNo + 1 < mission.maxRounds) {
          roundFeedback = action.note || '评审未通过，请改进后再交'
          tasks = round.tasks.map((t) => ({
            title: t.title,
            detail: t.detail,
            assignee: t.assignee,
          }))
          continue
        }
      }

      // 评审
      const verdict = await reviewRound(eng, mission, round)
      if (mission.cancelled) break
      if (verdict.approved || roundNo + 1 >= mission.maxRounds) {
        mission.status = 'converged'
        commitMission(eng, mission)
        await convergeMission(eng, mission)
        pushEvent(eng, mission.id, { type: 'mission/converged', missionId: mission.id })
        break
      }
      roundFeedback = verdict.note || '评审未通过'
      const followups = verdict.followups.length
        ? verdict.followups
        : round.tasks.map((t) => ({ title: t.title, detail: t.detail, assignee: t.assignee }))
      tasks = normalizeTaskList(followups, `r${roundNo + 2}`) ?? []
      if (!tasks.length) {
        mission.error = '评审打回但无法生成下轮任务'
        mission.status = 'failed'
        break
      }
    }

    if (mission.cancelled) {
      mission.status = 'cancelled'
    } else if (mission.status === 'dispatching' || mission.status === 'collecting') {
      mission.status = mission.rounds.length ? 'converged' : 'failed'
    }
  } catch (e: any) {
    mission.status = 'failed'
    mission.error = String(e && e.message ? e.message : e)
    engineLog(eng, `mission=${mission.id} FAILED: ${mission.error}`)
  } finally {
    commitMission(eng, mission)
    eng.aborters.delete(mission.id)
    eng.gateWaiters.delete(mission.id)
    eng.pauseWaiters.delete(mission.id)
    if (captain && typeof captain.dispose === 'function') {
      try { await captain.dispose() } catch { /* 兜底 */ }
    }
    eng.captainHandles.delete(mission.id)
    pushEvent(eng, mission.id, { type: 'mission/final', mission: snapshot(mission) })
    engineLog(eng, `mission=${mission.id} final=${mission.status}`)
  }
}

// ════════════════════════════════════════════════════════════════════════
// 插件主体
// ════════════════════════════════════════════════════════════════════════

export const name = '@dsh-external/dsh-agent-squad'
export const inject = ['tools', 'webServer', 'subagents', 'agents']

export function apply(ctx: AppContext, config: Config): void {
  const baseDir = config.dataDir || join(homedir(), '.dsh', 'dsh-agent-squad')
  const eng: Engine = {
    ctx,
    config,
    baseDir,
    missionsDir: join(baseDir, 'missions'),
    missions: new Map(),
    captainHandles: new Map(),
    gateWaiters: new Map(),
    pauseWaiters: new Map(),
    aborters: new Map(),
    sse: new Map(),
    logFile: join(baseDir, 'engine.log'),
  }
  mkdirSync(join(baseDir, 'missions'), { recursive: true })
  mkdirSync(join(baseDir, 'teams'), { recursive: true })

  // 恢复持久化的 mission（只登记状态，不复跑循环）
  try {
    const listDir = eng.missionsDir
    if (existsSync(listDir)) {
      for (const entry of readdirSafe(listDir)) {
        const m = loadMission(eng, entry)
        if (m && !['converged', 'cancelled', 'failed'].includes(m.status)) {
          m.status = 'failed'
          m.error = (m.error ? m.error + '；' : '') + '插件重载后未续跑，标记失败'
          commitMission(eng, m)
        }
        if (m) eng.missions.set(entry, m)
      }
    }
  } catch (e: any) {
    engineLog(eng, 'restore missions failed: ' + String(e))
  }

  const startMission = async (input: {
    objective: string
    constraints?: string
    expectation?: string
    teamId?: string
    maxRounds?: number
    gateRequired?: boolean
  }): Promise<Mission> => {
    const mission: Mission = {
      id: 'mission-' + randomUUID().slice(0, 12),
      objective: input.objective,
      constraints: input.constraints,
      expectation: input.expectation,
      teamId: input.teamId || 'standard-3',
      status: 'planning',
      paused: false,
      cancelled: false,
      createdAt: Date.now(),
      updatedAt: Date.now(),
      round: 0,
      maxRounds: input.maxRounds ?? config.defaultMaxRounds,
      gateRequired: input.gateRequired ?? config.gateRequired,
      rounds: [],
      artifacts: [],
    }
    eng.missions.set(mission.id, mission)
    commitMission(eng, mission)
    engineLog(eng, `mission=${mission.id} started: ${truncate(mission.objective, 120)}`)
    void runMission(eng, mission)
    return mission
  }

  // ── 工具注册（5 个，schema 精简：短 description、细节进结果）──
  const tools = ctx.effect(() => {
    return [
      ctx.tools.register(defineTool({
        name: 'squad_mission_start',
        description: '启动一个多 Agent 协作使命：队长分解任务并派发给并行子代理执行',
        parameters: {
          objective: { type: 'string', required: true, description: '目标' },
          constraints: { type: 'string', description: '约束' },
          expectation: { type: 'string', description: '验收期望' },
          teamId: { type: 'string', description: '团队模板 id（standard-3 / standard-2 / single-1）' },
          maxRounds: { type: 'integer', description: '最大回合数' },
          gateRequired: { type: 'boolean', description: '是否需人工闸门审批' },
        },
        output: {
          schema: { type: 'string' },
          render: (_args: any, value: any) => [{ type: 'text', text: String(value) }],
        },
        async execute(args: any) {
          const m = await startMission({
            objective: args.objective,
            constraints: args.constraints,
            expectation: args.expectation,
            teamId: args.teamId,
            maxRounds: args.maxRounds,
            gateRequired: args.gateRequired,
          })
          return `已启动使命 ${m.id}（${m.status}，最大 ${m.maxRounds} 轮）。用 squad_mission_status 跟进，闸门审批用 squad_mission_gate。`
        },
      }), 'dsh-agent-squad: squad_mission_start'),

      ctx.tools.register(defineTool({
        name: 'squad_mission_status',
        description: '查询使命当前状态、回合进度与各任务结果',
        parameters: {
          missionId: { type: 'string', required: true, description: '使命 id' },
        },
        output: {
          schema: { type: 'string' },
          render: (_args: any, value: any) => [{ type: 'text', text: String(value) }],
        },
        async execute(args: any) {
          const m = eng.missions.get(args.missionId) ?? loadMission(eng, args.missionId)
          if (!m) return `使命不存在: ${args.missionId}`
          return JSON.stringify(snapshot(m), null, 2)
        },
      }), 'dsh-agent-squad: squad_mission_status'),

      ctx.tools.register(defineTool({
        name: 'squad_mission_gate',
        description: '使命等待人工闸门时放行（approve）或打回（reject 附意见）',
        parameters: {
          missionId: { type: 'string', required: true, description: '使命 id' },
          action: { type: 'string', required: true, enum: ['approve', 'reject'], description: 'approve/reject' },
          note: { type: 'string', description: '意见' },
        },
        output: {
          schema: { type: 'string' },
          render: (_args: any, value: any) => [{ type: 'text', text: String(value) }],
        },
        async execute(args: any) {
          const m = eng.missions.get(args.missionId)
          if (!m) return `使命不存在: ${args.missionId}`
          if (m.status !== 'awaiting_gate') return `使命当前不在闸门等待（${m.status}）`
          const waiter = eng.gateWaiters.get(m.id)
          if (waiter) {
            waiter({ action: args.action, note: args.note })
            return `已${args.action === 'approve' ? '放行' : '打回'}使命 ${m.id}`
          }
          return `使命 ${m.id} 无待处理的闸门`
        },
      }), 'dsh-agent-squad: squad_mission_gate'),

      ctx.tools.register(defineTool({
        name: 'squad_mission_control',
        description: '暂停 / 恢复 / 取消使命运行',
        parameters: {
          missionId: { type: 'string', required: true, description: '使命 id' },
          action: { type: 'string', required: true, enum: ['pause', 'resume', 'cancel'], description: '操作' },
        },
        output: {
          schema: { type: 'string' },
          render: (_args: any, value: any) => [{ type: 'text', text: String(value) }],
        },
        async execute(args: any) {
          const m = eng.missions.get(args.missionId)
          if (!m) return `使命不存在: ${args.missionId}`
          if (args.action === 'cancel') {
            m.cancelled = true
            const waiter = eng.gateWaiters.get(m.id)
            if (waiter) waiter({ action: 'reject', note: '已取消' })
            const pw = eng.pauseWaiters.get(m.id)
            if (pw) { eng.pauseWaiters.delete(m.id); pw() }
            eng.aborters.get(m.id)?.abort('mission cancelled')
            commitMission(eng, m)
            return `已请求取消使命 ${m.id}`
          }
          if (args.action === 'pause') {
            if (m.paused) return `使命 ${m.id} 已处于暂停`
            m.paused = true
            commitMission(eng, m)
            return `已暂停使命 ${m.id}（将在当前阶段边界停下）`
          }
          if (args.action === 'resume') {
            if (!m.paused) return `使命 ${m.id} 未处于暂停`
            m.paused = false
            const pw = eng.pauseWaiters.get(m.id)
            if (pw) { eng.pauseWaiters.delete(m.id); pw() }
            commitMission(eng, m)
            return `已恢复使命 ${m.id}`
          }
          return '未知操作'
        },
      }), 'dsh-agent-squad: squad_mission_control'),

      ctx.tools.register(defineTool({
        name: 'squad_artifact_read',
        description: '读取使命产物内容（任务产物或最终报告）',
        parameters: {
          missionId: { type: 'string', required: true, description: '使命 id' },
          name: { type: 'string', required: true, description: '产物文件名（如 artifact-r1-1.md / report.md）' },
        },
        output: {
          schema: { type: 'string' },
          render: (_args: any, value: any) => [{ type: 'text', text: String(value) }],
        },
        async execute(args: any) {
          const file = join(eng.missionsDir, args.missionId, 'artifacts', args.name)
          if (!existsSync(file)) return `产物不存在: ${args.name}`
          const text = readFileSync(file, 'utf8')
          return truncate(text, 20000)
        },
      }), 'dsh-agent-squad: squad_artifact_read'),
    ]
  }, 'dsh-agent-squad: tools')

  // ── REST API（单前缀 + 内部派发，避免重复路由）──
  const route = ctx.effect(() => ctx.webServer.register({
    kind: 'prefix',
    path: '/dsh-agent-squad/api',
    handler: async (req: any, res: any) => {
      try {
        await handleApi(eng, req, res)
      } catch (e: any) {
        engineLog(eng, 'api error: ' + String(e))
        if (!res.writableEnded) {
          try {
            res.writeHead(500, { 'content-type': 'application/json; charset=utf-8' })
            res.end(JSON.stringify({ error: String(e && e.message ? e.message : e) }))
          } catch { /* 连接可能已断 */ }
        }
      }
    },
  }), 'dsh-agent-squad: api')

  // ── 卸载清理：取消全部使命、释放 captain ──
  const cleanup = ctx.effect(() => () => {
    try {
      for (const [id, ab] of eng.aborters) ab.abort('plugin unloaded')
      for (const [id, handle] of eng.captainHandles) {
        try { void Promise.resolve(handle.dispose?.()).catch(() => {}) } catch { /* 忽略 */ }
      }
      const [t, r] = [tools, route]
      void t; void r
    } catch { /* 忽略 */ }
  }, 'dsh-agent-squad: cleanup')

  void cleanup

  ctx.logger?.info?.('[dsh-agent-squad] 引擎就绪（dataDir=' + baseDir + ', squadProvider=' + config.squadProvider + '）')
}

// ════════════════════════════════════════════════════════════════════════
// HTTP 派发
// ════════════════════════════════════════════════════════════════════════

function readdirSafe(dir: string): string[] {
  try {
    const { readdirSync } = require('node:fs') as typeof import('node:fs')
    return readdirSync(dir, { withFileTypes: true })
      .filter((d) => d.isDirectory())
      .map((d) => d.name)
  } catch { return [] }
}

async function readBody(req: any): Promise<any> {
  const chunks: Buffer[] = []
  for await (const chunk of req) chunks.push(chunk as Buffer)
  if (!chunks.length) return {}
  const raw = Buffer.concat(chunks).toString('utf8')
  try { return JSON.parse(raw) } catch { return {} }
}

function sendJson(res: any, status: number, body: any): void {
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8' })
  res.end(JSON.stringify(body))
}

async function handleApi(eng: Engine, req: any, res: any): Promise<void> {
  const url = new URL(req.url ?? '/', 'http://localhost')
  const parts = url.pathname.split('/').filter(Boolean)
  // parts = ['dsh-agent-squad', 'api', ...]
  const method = (req.method || 'GET').toUpperCase()

  if (method === 'GET' && parts[2] === 'health') {
    sendJson(res, 200, { ok: true, version: '0.0.1', missions: eng.missions.size })
    return
  }
  if (method === 'GET' && parts[2] === 'teams') {
    sendJson(res, 200, { teams: TEAMS })
    return
  }
  if (method === 'GET' && parts[2] === 'missions' && !parts[3]) {
    const list = [...eng.missions.values()].map((m) => snapshot(m))
    sendJson(res, 200, { missions: list })
    return
  }
  if (method === 'POST' && parts[2] === 'missions' && !parts[3]) {
    const body = await readBody(req)
    if (!body.objective || typeof body.objective !== 'string') {
      sendJson(res, 400, { error: 'objective 必填' })
      return
    }
    const mission = await createAndStart(eng, body)
    sendJson(res, 201, { mission: snapshot(mission) })
    return
  }
  if (parts[2] === 'missions' && parts[3]) {
    const id = parts[3]
    if (method === 'GET' && parts[4] === 'stream') {
      await handleSse(eng, id, req, res)
      return
    }
    if (method === 'GET' && !parts[4]) {
      const m = eng.missions.get(id) ?? loadMission(eng, id)
      if (!m) { sendJson(res, 404, { error: 'not found' }); return }
      sendJson(res, 200, { mission: snapshot(m) })
      return
    }
    if (method === 'POST' && parts[4] === 'gate') {
      const body = await readBody(req)
      const m = eng.missions.get(id)
      if (!m) { sendJson(res, 404, { error: 'not found' }); return }
      if (m.status !== 'awaiting_gate') { sendJson(res, 400, { error: '不在闸门等待状态' }); return }
      const waiter = eng.gateWaiters.get(id)
      if (!waiter) { sendJson(res, 400, { error: '无待处理的闸门' }); return }
      waiter({ action: body.action === 'reject' ? 'reject' : 'approve', note: body.note })
      sendJson(res, 200, { ok: true })
      return
    }
    if (method === 'POST' && parts[4] === 'control') {
      const body = await readBody(req)
      const m = eng.missions.get(id)
      if (!m) { sendJson(res, 404, { error: 'not found' }); return }
      if (body.action === 'cancel') {
        m.cancelled = true
        eng.gateWaiters.get(id)?.({ action: 'reject', note: '已取消' })
        const pw = eng.pauseWaiters.get(id)
        if (pw) { eng.pauseWaiters.delete(id); pw() }
        eng.aborters.get(id)?.abort('mission cancelled')
        commitMission(eng, m)
        sendJson(res, 200, { ok: true })
        return
      }
      if (body.action === 'pause') {
        m.paused = true
        commitMission(eng, m)
        sendJson(res, 200, { ok: true })
        return
      }
      if (body.action === 'resume') {
        if (!m.paused) { sendJson(res, 400, { error: '未处于暂停' }); return }
        m.paused = false
        const pw = eng.pauseWaiters.get(id)
        if (pw) { eng.pauseWaiters.delete(id); pw() }
        commitMission(eng, m)
        sendJson(res, 200, { ok: true })
        return
      }
      sendJson(res, 400, { error: '未知操作' })
      return
    }
    if (method === 'GET' && parts[4] === 'artifacts' && parts[5]) {
      const file = join(eng.missionsDir, id, 'artifacts', parts[5])
      if (!existsSync(file)) { sendJson(res, 404, { error: 'artifact not found' }); return }
      res.writeHead(200, { 'content-type': 'text/plain; charset=utf-8' })
      res.end(readFileSync(file, 'utf8'))
      return
    }
  }
  sendJson(res, 404, { error: 'not found' })
}

async function createAndStart(eng: Engine, body: any): Promise<Mission> {
  const mission: Mission = {
    id: 'mission-' + randomUUID().slice(0, 12),
    objective: body.objective,
    constraints: body.constraints,
    expectation: body.expectation,
    teamId: body.teamId || 'standard-3',
    status: 'planning',
    paused: false,
    cancelled: false,
    createdAt: Date.now(),
    updatedAt: Date.now(),
    round: 0,
    maxRounds: body.maxRounds ?? eng.config.defaultMaxRounds,
    gateRequired: body.gateRequired ?? eng.config.gateRequired,
    rounds: [],
    artifacts: [],
  }
  eng.missions.set(mission.id, mission)
  commitMission(eng, mission)
  engineLog(eng, `mission=${mission.id} started via API: ${truncate(mission.objective, 120)}`)
  void runMission(eng, mission)
  return mission
}

async function handleSse(eng: Engine, missionId: string, req: any, res: any): Promise<void> {
  const m = eng.missions.get(missionId) ?? loadMission(eng, missionId)
  if (!m) {
    sendJson(res, 404, { error: 'not found' })
    return
  }
  res.writeHead(200, {
    'content-type': 'text/event-stream; charset=utf-8',
    'cache-control': 'no-cache',
    connection: 'keep-alive',
  })
  res.write('data: ' + JSON.stringify({ type: 'hello', mission: snapshot(m) }) + '\n\n')
  const listener = (evt: any) => {
    try { res.write('data: ' + JSON.stringify(evt) + '\n\n') } catch { /* 断开忽略 */ }
  }
  let set = eng.sse.get(missionId)
  if (!set) { set = new Set(); eng.sse.set(missionId, set) }
  set.add(listener)
  const heartbeat = setInterval(() => {
    try { res.write(': ping\n\n') } catch { /* 忽略 */ }
  }, 15000)
  req.on('close', () => {
    clearInterval(heartbeat)
    const s = eng.sse.get(missionId)
    if (s) s.delete(listener)
  })
  req.on('error', () => {
    clearInterval(heartbeat)
    const s = eng.sse.get(missionId)
    if (s) s.delete(listener)
  })
}

