export const inject = ['slots']

const badgeColor = (status: string): string => {
  switch (status) {
    case 'converged': return 'var(--dsw-alias-state-success-primary)'
    case 'failed':
    case 'cancelled': return 'var(--dsw-alias-state-error-primary)'
    case 'awaiting_gate': return 'var(--dsw-alias-state-warn-primary)'
    default: return 'var(--dsw-alias-label-secondary)'
  }
}

function SquadPanel() {
  const [missions, setMissions] = useState<any[]>([])
  const [stamp, setStamp] = useState('')
  useEffect(() => {
    let alive = true
    const tick = async () => {
      try {
        const r = await fetch('/dsh-agent-squad/api/missions')
        const j = await r.json()
        if (alive && j && Array.isArray(j.missions)) {
          setMissions(j.missions)
          setStamp(new Date().toLocaleTimeString())
        }
      } catch { /* host API 未就绪时静默 */ }
    }
    void tick()
    const iv = setInterval(tick, 4000)
    return () => { alive = false; clearInterval(iv) }
  }, [])

  const root: any = {
    background: 'var(--dsw-alias-bg-layer-1)',
    border: '1px solid var(--dsw-alias-border-l2)',
    borderRadius: '16px',
    padding: '12px 16px',
    margin: '8px',
    fontFamily: 'var(--dsw-font-family)',
    fontSize: '13px',
    lineHeight: '20px',
    color: 'var(--dsw-alias-label-primary)',
  }
  const title: any = {
    fontSize: '14px',
    fontWeight: 600,
    color: 'var(--dsw-alias-label-primary)',
    marginBottom: '8px',
  }
  const row: any = {
    display: 'flex',
    gap: '8px',
    alignItems: 'center',
    padding: '4px 0',
    borderBottom: '1px solid var(--dsw-alias-border-l1)',
  }
  const badge: any = {
    padding: '1px 8px',
    borderRadius: '12px',
    fontSize: '12px',
    background: 'var(--dsw-alias-interactive-bg-hover)',
    color: badgeColor(''),
  }

  return jsx('div', { style: root, children: [
    jsx('div', { style: title, children: 'dsh-agent-squad 指挥室' }),
    missions.length === 0
      ? jsx('div', { style: { color: 'var(--dsw-alias-label-tertiary)' }, children: '暂无使命。用 squad_mission_start 工具或 API 发起使命。' })
      : missions.map((m: any) => jsx('div', { key: m.id, style: row, children: [
          jsx('span', { style: { fontFamily: 'var(--ds-font-family-code)', color: 'var(--dsw-alias-label-secondary)' }, children: m.id }),
          jsx('span', { style: { ...badge, color: badgeColor(m.status) }, children: m.status }),
          jsx('span', { style: { color: 'var(--dsw-alias-label-tertiary)', overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }, children: m.objective }),
        ] })),
    jsx('div', { style: { color: 'var(--dsw-alias-label-dimmed)', fontSize: '11px', marginTop: '6px' }, children: '刷新于 ' + (stamp || '…') }),
  ] })
}

export function apply(ctx: ClientContext): void {
  ctx.effect(() => ctx.slots.inject('conversation.view', () =>
    ctx.slots.register({
      name: 'conversation.view',
      id: '@dsh-external/dsh-agent-squad-panel',
      label: () => 'dsh-agent-squad 指挥室',
      component: () => jsx(SquadPanel, {}),
    }),
  ), '@dsh-external/dsh-agent-squad: panel')
}

