// ────────────────────────────────────────────────────────────────────────
// 令牌（--dsw-* 设计令牌，深色模式自动跟随；禁止硬编码色值）
// ────────────────────────────────────────────────────────────────────────

const T = {
  bgCard: 'var(--dsw-alias-bg-layer-1)',
  bgHover: 'var(--dsw-alias-interactive-bg-hover)',
  border1: 'var(--dsw-alias-border-l1)',
  border2: 'var(--dsw-alias-border-l2)',
  label1: 'var(--dsw-alias-label-primary)',
  label2: 'var(--dsw-alias-label-secondary)',
  label3: 'var(--dsw-alias-label-tertiary)',
  labelDim: 'var(--dsw-alias-label-dimmed)',
  success: 'var(--dsw-alias-state-success-primary)',
  warn: 'var(--dsw-alias-state-warn-primary)',
  error: 'var(--dsw-alias-state-error-primary)',
  info: 'var(--dsw-alias-state-info-primary)',
  font: 'var(--dsw-font-family)',
  fontCode: 'var(--ds-font-family-code)',
} as const

// 状态 → 语义色（点/徽标）
function statusColor(status: string): string {
  switch (status) {
    case 'converged': return T.success
    case 'failed':
    case 'cancelled': return T.error
    case 'awaiting_gate': return T.warn
    case 'planning':
    case 'dispatching':
    case 'collecting':
    case 'reviewing': return T.info
    default: return T.label2
  }
}

function taskStatusColor(status: string): string {
  switch (status) {
    case 'done': return T.success
    case 'failed': return T.error
    case 'running': return T.info
    default: return T.label3 // pending
  }
}

function statusText(status: string): string {
  switch (status) {
    case 'planning': return '规划中'
    case 'dispatching': return '派发中'
    case 'collecting': return '收集中'
    case 'awaiting_gate': return '待审批'
    case 'reviewing': return '评审中'
    case 'converged': return '已完成'
    case 'cancelled': return '已取消'
    case 'failed': return '失败'
    default: return status
  }
}

// ────────────────────────────────────────────────────────────────────────
// 输入框上方横向 Agent 卡片条（conversation.input.dock）
// ────────────────────────────────────────────────────────────────────────

function SquadDock() {
  const [missions, setMissions] = useState<any[]>([])
  useEffect(() => {
    let alive = true
    const tick = async () => {
      try {
        const r = await fetch('/dsh-agent-squad/api/missions')
        const j = await r.json()
        if (alive && j && Array.isArray(j.missions)) setMissions(j.missions)
      } catch { /* host API 未就绪时静默 */ }
    }
    void tick()
    const iv = setInterval(tick, 3000)
    return () => { alive = false; clearInterval(iv) }
  }, [])

  // 只展示运行态使命（planning→reviewing / awaiting_gate），
  // 终态（converged/cancelled/failed）静默收起，不占输入区。
  const active = (missions || []).filter(
    (m: any) => !['converged', 'cancelled', 'failed'].includes(m.status),
  )
  if (!active.length) return null

  // 展平为 agent 行：队长卡 + 最新一轮每任务一张 worker 卡
  const rows: any[] = []
  for (const m of active) {
    rows.push({ key: m.id + '/captain', mission: m, kind: 'captain' })
    const round = m.current
    if (round && Array.isArray(round.tasks)) {
      for (const t of round.tasks) {
        rows.push({ key: m.id + '/' + t.id, mission: m, kind: 'worker', task: t })
      }
    }
  }

  const strip: any = {
    display: 'flex',
    gap: '8px',
    overflowX: 'auto',
    padding: '4px 2px',
    alignItems: 'stretch',
    width: '100%',
    maxHeight: '72px',
  }

  return jsx('div', { style: strip, children: rows.map((row) => {
    const { mission } = row
    const status = mission.status
    const accent = statusColor(status)
    const isCaptain = row.kind === 'captain'

    const card: any = {
      display: 'flex',
      gap: '8px',
      alignItems: 'center',
      flex: '0 0 auto',
      padding: '6px 10px',
      borderRadius: '12px',
      background: T.bgCard,
      border: '1px solid ' + (status === 'awaiting_gate' ? T.warn : T.border1),
      boxShadow: status === 'awaiting_gate' ? '0 0 0 1px var(--dsw-alias-state-warn-primary)' : undefined,
      minWidth: '172px',
      maxWidth: '240px',
      fontFamily: T.font,
    }

    // 角色徽标（队长=星形；worker=角色首字符）
    const avatar: any = {
      width: '26px',
      height: '26px',
      borderRadius: '50%',
      flex: '0 0 26px',
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      fontSize: '12px',
      fontWeight: 600,
      color: accent,
      background: 'var(--dsw-alias-interactive-bg-hover)',
      border: '1px solid ' + accent,
    }
    const avatarGlyph = isCaptain ? '★' : (row.task.assignee || 'w').slice(0, 1).toUpperCase()

    const title: any = {
      display: 'flex',
      alignItems: 'center',
      gap: '6px',
      fontSize: '12px',
      fontWeight: 600,
      color: T.label1,
      whiteSpace: 'nowrap',
    }
    const sub: any = {
      fontSize: '11px',
      color: T.label3,
      overflow: 'hidden',
      textOverflow: 'ellipsis',
      whiteSpace: 'nowrap',
      maxWidth: '150px',
    }
    const dot: any = { width: '7px', height: '7px', borderRadius: '50%', flex: '0 0 7px' }

    const body: any = {
      display: 'flex',
      flexDirection: 'column',
      gap: '2px',
      minWidth: '0',
    }

    // worker 卡：任务状态点 + 角色名 + 任务标题；队长卡：使命状态点 + 队长 + 目标
    const dotColor = isCaptain
      ? accent
      : taskStatusColor(row.task ? row.task.status : 'pending')
    const name = isCaptain ? '队长' : (row.task.assignee || 'worker')
    const text = isCaptain
      ? (mission.objective || '').slice(0, 36)
      : ((row.task && row.task.title) || '').slice(0, 24)

    const statusTag: any = {
      fontSize: '11px',
      color: dotColor,
      flex: '0 0 auto',
    }

    const gateBtn =
      !isCaptain && status === 'awaiting_gate'
        ? jsx('button', {
            onClick: (e: any) => {
              e.stopPropagation()
              const qs = encodeURIComponent('approve')
              void fetch(`/dsh-agent-squad/api/missions/${mission.id}/gate?action=${qs}`)
            },
            style: {
              background: T.warn,
              color: '#fff',
              border: 'none',
              borderRadius: '8px',
              padding: '2px 8px',
              fontSize: '11px',
              cursor: 'pointer',
              flex: '0 0 auto',
            },
            children: '放行',
          })
        : null

    return jsx('div', {
      key: row.key,
      style: card,
      title: (isCaptain ? '队长 · ' + mission.id : row.task.assignee + ' · ' + (row.task || {}).title) + '\n' + mission.objective,
      children: [
        jsx('div', { style: avatar, children: avatarGlyph }),
        jsx('div', { style: body, children: [
          jsx('div', { style: title, children: [
            jsx('span', { children: name }),
            jsx('span', { style: { ...dot, background: dotColor }, children: null }),
            jsx('span', { style: statusTag, children: isCaptain ? statusText(status) : '' }),
          ] }),
          jsx('div', { style: sub, children: text }),
        ] }),
        gateBtn,
      ],
    })
  }) })
}

