function Apply-Theme([bool]$light) {
  $p = Build-Paint $light
  $script:cur = $p
  # F1：玻璃层独立——alpha（玻璃透明度）只作用于玻璃/卡面/高光，文字永全不透明
  $aK = [double]$script:cfg.alpha / 100.0   # 玻璃透明度系数 0.40..1.00（alpha=100 即 v0.5.0 原貌）
  if ($script:acrylicOn) {
    # 真·液态玻璃：窗口底色 = DWM Acrylic 着色；着色强度随 alpha（透出桌面量）+ cardAlpha 变化加深，
    # 真正的模糊由 DWM 合成器在背后完成；卡片透出模糊背景。
    $tintA = [int][Math]::Round($aK * $p.ck * 70)
    if ($tintA -lt 18) { $tintA = 18 }
    if ($tintA -gt 255) { $tintA = 255 }
    $baseCol = if ($light) { '#FFFFFF' } else { '#0E1320' }
    $win.Background = (New-Brush $baseCol $tintA)
    $u.Card.Background = $null
    $u.UsageCard.Background = $null
  } else {
    # Win10 降级：纯色半透明卡片；卡面透出桌面随 alpha + cardAlpha 变化
    $win.Background = [System.Windows.Media.Brushes]::Transparent
    $cardBg = New-Brush $p.surface
    $cardBg.Opacity = $aK * $p.ck
    $u.Card.Background = $cardBg
    $u.UsageCard.Background = $cardBg
  }

