// 账户余额（与桌面壳层 balance.js 同口径）：
//   密钥：env DEEPSEEK_API_KEY > ~/.dsh/.credentials.yaml 的 DEEPSEEK_API_KEY 行
//   端点：env DEEPSEEK_BALANCE_URL > (DEEPSEEK_API_BASE 或 https://api.deepseek.com)/user/balance
// 语义：total=available=total_balance（当前余额）；granted/toppedUp 为拆分；无 key → {error:'no-api-key'}
// ──────────────────────────────────────────────────────────────
function dshHome() {
  return safe(() => join(homedir(), '.dsh'), join(process.cwd(), '.dsh'));
}

function readApiKey() {
  const envKey = process.env.DEEPSEEK_API_KEY;
  if (envKey) return envKey.trim();
  try {
    const text = readFileSync(join(dshHome(), '.credentials.yaml'), 'utf8');
    for (const line of text.split(/\r?\n/)) {
      const m = line.match(/^\s*DEEPSEEK_API_KEY\s*:\s*["']?([^"'\s#]+)/);
      if (m) return m[1];
    }
  } catch { /* 无凭据文件 */ }
  return '';
}

function balanceEndpoint() {
  if (process.env.DEEPSEEK_BALANCE_URL) return process.env.DEEPSEEK_BALANCE_URL;
  const base = (process.env.DEEPSEEK_API_BASE || 'https://api.deepseek.com').replace(/\/+$/, '');
  return base + '/user/balance';
}

function fetchBalance(json) {
  return new Promise((resolve, reject) => {
    const req = https.get(
      balanceEndpoint(),
      { headers: { Authorization: 'Bearer ' + readApiKey(), 'User-Agent': 'DSH-Desktop' } },
      (res) => {
        let body = '';
        res.setEncoding('utf8');
        res.on('data', (c) => {
          body += c;
          if (body.length > 1024 * 1024) req.destroy(new Error('响应过大'));
        });
        res.on('end', () => {
          if (res.statusCode !== 200) {
            const hint = body.slice(0, 200).trim();
            return reject(new Error('HTTP ' + res.statusCode + (hint ? '：' + hint : '')));
          }
          try { resolve(body.length ? JSON.parse(body) : {}); }
          catch { reject(new Error('JSON 解析失败')); }
        });
      }
    );
    req.setTimeout(15000, () => req.destroy(new Error('请求超时')));
    req.on('error', reject);
  });
}

