        ? total
        : total,
      granted: Number(info.granted_balance) || 0,
      toppedUp: Number(info.topped_up_balance) || 0,
      error: null,
    };
  } catch (err) {
    state.balance = { error: String((err && err.message) || err) };
  }
  markDirty();
}
