    # 圆角=20 裁剪整窗含边距，Accent 模糊随区域裁剪 → 圆角液态玻璃。
    # ⚠ WPF $win.Width/Height 是逻辑单位（DPI 无关），而 SetWindowRgn 需要物理像素：
    #   高 DPI（125%/150%）下用逻辑尺寸会导致裁剪区域小于实际窗口、四角漏出。按 DPI 换算。
    $dpi = 1.0
    try {
      $src = [System.Windows.PresentationSource]::FromVisual($win)
      if ($null -ne $src -and $null -ne $src.CompositionTarget) {
        $dpi = $src.CompositionTarget.TransformToDevice.M11
      }
    } catch {}
    if ($dpi -lt 0.5 -or $dpi -gt 8) { $dpi = 1.0 }
    $r = 20
    $w = [int][math]::Round($win.Width * $dpi); $h = [int][math]::Round($win.Height * $dpi)
    $hrgn = [DshW.Native]::CreateRoundRectRgn(0, 0, $w, $h, $r, $r)
    [void][DshW.Native]::SetWindowRgn($script:hwnd, $hrgn, $true)
  } catch {}
}

