function lanAddresses() {
  const out = [];
  let ifaces;
  try {
    ifaces = networkInterfaces();
  } catch {
    return out;
  }
  for (const key of Object.keys(ifaces)) {
    for (const ni of ifaces[key] || []) {
      if (ni.family === "IPv4" && !ni.internal && ni.address) out.push(ni.address);
    }
  }
  return out;
}

function gatewayStatus(ctx) {
  const cfg = loadConfig();
  const webServer = ctx.get("webServer");
  const host = (webServer && webServer.host) || "127.0.0.1";
  const port = (webServer && webServer.port) || 0;
  const ips = lanAddresses();
  const reachable = cfg.lanEnabled && host === "0.0.0.0" && port > 0;
  const token = effectiveToken();
  let url = "";
  if (reachable && ips.length) {
    url = `http://${ips[0]}:${port}${APP_PREFIX}/?token=${encodeURIComponent(token)}`;
  } else if (port > 0) {
    url = `http://127.0.0.1:${port}${APP_PREFIX}/?token=${encodeURIComponent(token)}`;
  }
  return {
    version: PLUGIN_VERSION,
    token,
    hasToken: Boolean(token),
    lanEnabled: cfg.lanEnabled,
    maxUploadMb: cfg.maxUploadMb,
    host,
    port,
    lanIps: ips,
    reachable,
    url,
    bindWarn: cfg.lanEnabled && host !== "0.0.0.0"
      ? "DSH web 服务当前绑定 127.0.0.1，手机无法访问。请以 --host 0.0.0.0 启动 dsh web（或修改 DSH Desktop 对应设置）后重试。"
      : null,
  };
}

