// SSE live-delivery probe v2: fixed-duration collection.
const BASE = "http://127.0.0.1:46321/dsh-mini/api";
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

async function main() {
  const nr = await fetch(BASE + "/threads/new", { method: "POST" });
  const { id } = await nr.json();
  console.log("session:", id);

  const ac = new AbortController();
  let steps = 0;
  const types = new Set();
  const statusEvents = [];
  let done = false;

  const readerLoop = (async () => {
    const r = await fetch(BASE + "/threads/" + encodeURIComponent(id) + "/stream", { signal: ac.signal });
    const reader = r.body.getReader();
    const dec = new TextDecoder();
    let buf = "";
    try {
      while (true) {
        const { done: d, value } = await reader.read();
        if (d) break;
        buf += dec.decode(value, { stream: true });
        let idx;
        while ((idx = buf.indexOf("\n\n")) >= 0) {
          const frame = buf.slice(0, idx);
          buf = buf.slice(idx + 2);
          if (frame.startsWith("event: step")) {
            steps++;
            const dataLine = frame.split("\n").find((l) => l.startsWith("data: "));
            if (dataLine) {
              try {
                const d2 = JSON.parse(dataLine.slice(6));
                types.add(d2.type);
                if (d2.type === "status") statusEvents.push(d2.status + (d2.reason ? "/" + d2.reason : ""));
                if (d2.type === "assistant") process.stdout.write(d2.text.slice(-20));
              } catch {}
            }
          }
        }
      }
    } catch (e) {
      /* aborted */
    } finally {
      done = true;
    }
  })();

  await sleep(1200);
  const sendRes = await fetch(BASE + "/threads/" + encodeURIComponent(id) + "/send", {
    method: "POST",
    headers: { "content-type": "application/json" },
    body: JSON.stringify({ text: "回复两个字：收到" }),
  });
  console.log("\nsend:", sendRes.status);

  await sleep(25000);
  ac.abort();
  await sleep(500);
  console.log("RESULT: steps=" + steps + " types=" + JSON.stringify([...types]) + " status=" + JSON.stringify(statusEvents) + " done=" + done);
  if (steps === 0) process.exit(1);
}

main().catch((e) => { console.error("FAIL:", e && e.message); process.exit(1); });

