        (tmodel ? '<span class="tmodel">' + esc(tmodel) + "</span>" : "") + "</span>" +
        '<span class="thread-option-state">' + st + "</span>";
      opt.onclick = () => { toggleMenu(false); openChat(t.id, t.title || t.id); };
      listDiv.appendChild(opt);
    }
