(function initSafeAreas() {
  const dpr = window.devicePixelRatio || 1;
  try {
    var b = window.DshMiniBridge;
    if (b && b.getSafeTop) {
      var t = Number(b.getSafeTop()) || 0;
      if (t > 0) document.documentElement.style.setProperty("--dsh-safe-top", Math.round(t / dpr) + "px");
    }
    if (b && b.getSafeBottom) {
      var bt = Number(b.getSafeBottom()) || 0;
      if (bt > 0) document.documentElement.style.setProperty("--dsh-safe-bottom", Math.round(bt / dpr) + "px");
    }
